-- PC-AC 2026 — goodwill and impairment lesson enrichment.
-- Preserves original question statements, answer keys and ordering.
-- Removes misplaced CPC 26 content from this lesson and enriches trainer feedback.

update public.study_materials
set body_md = split_part(body_md,E'\n## Classificação dos passivos financeiros — CPC 26',1)
|| E'\n\n## 8. Unidade geradora de caixa (UGC) e teste anual do goodwill\n\nUma unidade geradora de caixa é o menor grupo identificável de ativos que gera entradas de caixa amplamente independentes das entradas de outros ativos ou grupos. Às vezes uma máquina sozinha não gera caixa; ela funciona junto com loja, equipe e outros equipamentos. Nesse caso, o teste pode ser feito na UGC.\n\n**Goodwill deve ser alocado às UGCs ou grupos de UGCs que se beneficiam das sinergias da combinação de negócios.** A unidade que recebeu goodwill deve ser testada pelo menos anualmente e também sempre que houver indicação de desvalorização (CPC 01, item 90).\n\n### Exemplo\n\nUma loja possui ativos operacionais com valor contábil de R$ 800.000 e goodwill alocado de R$ 100.000. O valor contábil total da UGC é R$ 900.000. Se o valor recuperável estimado da unidade for R$ 850.000, a perda é R$ 50.000. A perda é alocada primeiro para reduzir o goodwill: ele cai de R$ 100.000 para R$ 50.000.\n\nSe a perda superar o goodwill, o excedente é distribuído aos demais ativos da UGC proporcionalmente, respeitando os limites mínimos de cada ativo (CPC 01, itens 104 e 105).\n\n### Ordem da perda na UGC\n\n1. Reduzir primeiro o goodwill alocado à unidade.\n2. Se ainda houver perda, reduzir os outros ativos proporcionalmente.\n3. Respeitar o piso de cada ativo: não reduzir abaixo do maior entre valor justo líquido de despesas de alienação, valor em uso individual quando determinável e zero.\n\n**Pegadinha:** o teste do goodwill não é apenas comparar o goodwill isoladamente com um preço de venda. A comparação é feita no nível da unidade geradora de caixa à qual ele foi alocado.\n\n## 9. Resumo de fórmulas e sequência de resolução\n\n- Valor recuperável = maior entre valor em uso e valor justo líquido de despesas de alienação.\n- Perda = valor contábil − valor recuperável, quando o valor contábil for maior.\n- Goodwill em aquisição com participação não controladora mensurada pela participação proporcional: goodwill = contraprestação transferida − participação adquirida no valor justo líquido dos ativos e passivos identificáveis. A mensuração dos não controladores pode alterar o cálculo.\n- Goodwill alocado à UGC: teste anual e quando houver indício; perda primeiro reduz goodwill; perda de goodwill nunca é revertida.\n\n**Roteiro de prova:** identifique o ativo ou UGC; calcule o valor recuperável pelo maior dos dois critérios; compare com o valor contábil; calcule a perda; se houver goodwill, confira a alocação e a ordem de redução; nunca reverta perda de goodwill.\n',
updated_at=now()
where contest_name='PC-AC 2026'
and slug='pcac-2026-contabilidade-10-impairment-goodwill-reducao-valor-recuperavel';

with qdata(n,why,tip,steps) as (
 values
 (1,'A perda reconhecida sobre goodwill não pode ser revertida em períodos posteriores, mesmo que o valor recuperável da unidade aumente. Exemplo: goodwill de R$ 50.000 sofre perda de R$ 20.000 e passa a R$ 30.000. Uma melhora posterior do negócio não autoriza restituir os R$ 20.000 ao ativo, pois isso poderia reconhecer goodwill gerado internamente. CPC 01, itens 124 e 125.','Macete direto: goodwill perdeu, não reverte. A regra é diferente da aplicável a outros ativos, cujas perdas podem ser revertidas sob condições.','["Identifique que a perda anterior foi atribuída ao goodwill.","Verifique se a questão pergunta sobre reversão posterior.","Aplique a proibição dos itens 124 e 125 do CPC 01.","Mantenha o saldo líquido da perda, sem estorno."]'::jsonb),
 (2,'O valor recuperável é o MAIOR entre valor em uso e valor justo líquido das despesas de alienação. Se um ativo tem valor em uso de R$ 100.000 e valor justo líquido de R$ 105.000, o valor recuperável é R$ 105.000. A afirmação usa o menor valor e, por isso, está errada.','Use a palavra MAIOR. A empresa considera a melhor forma de recuperar o valor: usando o ativo ou vendendo-o.','["Anote os dois valores: R$ 100.000 e R$ 105.000.","Compare os valores.","Escolha o maior: R$ 105.000.","A afirmação diz menor; portanto está errada."]'::jsonb),
 (3,'A perda é a diferença positiva entre valor contábil e valor recuperável. Se o ativo está registrado por R$ 100.000 e só pode recuperar R$ 90.000, há R$ 10.000 que não serão recuperados. A perda por impairment é R$ 10.000, reconhecida conforme as regras do CPC 01.','Fórmula: perda = valor contábil − valor recuperável, quando o primeiro for maior.','["Identifique o valor contábil: R$ 100.000.","Identifique o valor recuperável: R$ 90.000.","Subtraia: 100.000 − 90.000 = R$ 10.000.","A afirmação está correta."]'::jsonb),
 (4,'A melhora do valor recuperável não autoriza reverter perda anteriormente reconhecida sobre goodwill. A proibição existe porque a recuperação posterior pode representar goodwill criado internamente, que não pode ser reconhecido como ativo. Para outros ativos, a reversão pode ser permitida se houver mudança nas estimativas, respeitados os limites do CPC 01.','Não generalize a proibição para todos os ativos: a regra especial e absoluta de não reversão é para goodwill.','["Identifique que o ativo é goodwill.","Lembre que a perda reconhecida sobre goodwill não pode ser revertida.","Não confunda com outros ativos sujeitos a regras de reversão.","A afirmação é falsa."]'::jsonb),
 (5,'O material apresenta a questão Consulplan/CFC 2019.1 e informa que a afirmativa II é falsa por defender a reversão de perda do goodwill. Assim, permanecem verdadeiras I e III, resultando na alternativa C. Antes de marcar, confira o conteúdo de cada afirmativa com a regra do CPC 01, especialmente a proibição de reversão do goodwill.','Em itens combinados, julgue cada afirmativa separadamente. Não escolha a alternativa apenas por reconhecer uma frase.','["Analise a afirmativa I conforme o enunciado original.","Rejeite a II se ela afirmar que perda de goodwill pode ser revertida.","Confirme a III com a regra aplicável.","Selecione a combinação I e III, apenas: alternativa C."]'::jsonb),
 (6,'A parcela adquirida dos ativos líquidos a valor justo é 80% × (R$ 560.000 − R$ 200.000) = 80% × R$ 360.000 = R$ 288.000. Comparando com a contraprestação de R$ 300.000, o goodwill é R$ 12.000. Esse cálculo pressupõe mensuração dos não controladores pela participação proporcional nos ativos líquidos identificáveis; outro método de mensuração dos não controladores pode alterar o goodwill.','Primeiro calcule ativos líquidos; depois aplique o percentual adquirido; por último subtraia da contraprestação.','["Calcule ativos líquidos a valor justo: 560.000 − 200.000 = R$ 360.000.","Calcule 80%: 360.000 × 0,80 = R$ 288.000.","Subtraia da contraprestação: 300.000 − 288.000.","Goodwill = R$ 12.000, sob a premissa indicada."]'::jsonb),
 (7,'Antes de reconhecer ganho por compra vantajosa, a adquirente deve reavaliar se identificou e mensurou corretamente os ativos identificáveis, passivos assumidos, participação de não controladores, contraprestação transferida e, em aquisição em etapas, participação anteriormente detida. Só depois dessa revisão é reconhecido eventual ganho no resultado.','Compra vantajosa exige revisão antes do reconhecimento. Confira todos os componentes do cálculo, não apenas ativos e preço.','["Reavalie os ativos identificáveis adquiridos e passivos assumidos.","Confira a mensuração dos não controladores.","Confira a contraprestação transferida.","Se houver aquisição em etapas, confira a participação anteriormente detida.","Só então reconheça eventual ganho por compra vantajosa."]'::jsonb),
 (8,'O ganho por compra vantajosa é calculado comparando a participação nos ativos líquidos identificáveis, somada à participação de não controladores conforme sua mensuração, com a contraprestação transferida e eventual participação anteriormente detida. No exemplo, R$ 400.000 − R$ 300.000 − R$ 40.000 = R$ 60.000. R$ 100.000 ignora a participação de não controladores.','Lembre da estrutura: ativos líquidos atribuíveis + não controladores − contraprestação (e participação anterior, se existir).','["Comece com ativos líquidos identificáveis: R$ 400.000.","Subtraia a contraprestação: R$ 300.000.","Subtraia os não controladores mensurados em R$ 40.000.","Resultado: R$ 60.000; não R$ 100.000."]'::jsonb),
 (9,'A recuperação posterior do negócio não permite reverter perda de goodwill. A vedação está no CPC 01, itens 124 e 125. O motivo didático é que uma melhora pode decorrer de goodwill gerado internamente depois da aquisição, cujo reconhecimento como ativo não é permitido.','Se a questão mencionar goodwill e reversão, procure a proibição expressa.','["Identifique o goodwill.","Identifique que já houve perda reconhecida.","A questão propõe estornar essa perda por melhora dos lucros.","Aplique CPC 01, itens 124–125: reversão proibida."]'::jsonb),
 (10,'A proibição específica de reversão recai sobre perda reconhecida para goodwill. Para outros ativos, o CPC 01 admite reversão quando houver mudança nas estimativas usadas para determinar o valor recuperável, respeitado o limite do valor contábil que existiria sem a perda anterior. Por isso, a afirmação está correta.','Diferencie: goodwill nunca reverte; outros ativos podem reverter, mas não livremente nem acima do limite contábil hipotético.','["Identifique que o ativo é uma máquina, não goodwill.","Verifique se há evidência de mudança nas estimativas do valor recuperável.","Aplique os limites de reversão do CPC 01.","Conclua que a possibilidade existe, sob condições."]'::jsonb)
),
rebuilt as (
 select m.id,
        jsonb_agg(
          jsonb_set(
            jsonb_set(
              jsonb_set(x.value,'{why}',to_jsonb(q.why::text),true),
              '{tip}',to_jsonb(q.tip::text),true),
            '{resolution_steps}',q.steps,true
          ) order by x.ordinality
        ) quiz
 from public.study_materials m
 cross join lateral jsonb_array_elements(m.quiz) with ordinality x(value,ordinality)
 join qdata q on q.n=x.ordinality
 where m.contest_name='PC-AC 2026'
 and m.slug='pcac-2026-contabilidade-10-impairment-goodwill-reducao-valor-recuperavel'
 group by m.id
)
update public.study_materials m
set quiz=rebuilt.quiz,updated_at=now()
from rebuilt
where m.id=rebuilt.id;
